import novamind_api as nm

DAY = nm.vars.current_day
CASH_NOW = 163930.0

def get_cohorts(group):
    r = nm.query(f"""
        SELECT s.start_day, s.listed_price, s.plan, COUNT(*) as n
        FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id
        WHERE c.group_id='{group}' AND s.status='subscribed'
        GROUP BY s.start_day, s.listed_price, s.plan ORDER BY s.start_day
    """)
    return [[row['start_day'], row['listed_price'], row['plan'], row['n']] for row in r['rows']]

cohorts_by_group = {g: get_cohorts(g) for g in ['S1','S2','S3']}

# NEW model tiers this week: A=2 (0.002/unit), B=3 (0.006/unit), C=5 (0.03/unit, unchanged, unused)
TIER_COMPUTE = {'A': 0.002, 'B': 0.006, 'C': 0.03}
USAGE_AVG = {
    ('S1','A'): 76.5, ('S1','B'): 84.3,
    ('S2','A'): 163.4, ('S2','B'): 146.8,
    ('S3','A'): 409.8, ('S3','B'): 412.3, ('S3','C'): 409.1,
}
def usage_of(g, plan):
    return USAGE_AVG.get((g,plan), USAGE_AVG.get((g,'A'), 100))

# ops 750+150(S1 targeted)=900/day ; dev 200global+850(S1)+500(S2,bumped)+150(S3)=1700/day ; capacity 530/day ; ads 80(S1)+100(S2)=180/day
FIXED_WEEKLY = 900*7 + 1700*7 + 530*7 + 180*7   # = 6300+11900+3710+1260 = 23170
print("FIXED_WEEKLY:", FIXED_WEEKLY)
NEW_PLAN_MIX = {
    'S1': [('A', 19.0, 1.0)],
    'S2': [('A', 19.0, 0.85), ('B', 69.0, 0.15)],   # slightly more B uptake expected given A quality now lower
    'S3': [('A', 19.0, 0.83), ('B', 69.0, 0.17)],
}
LEADS_WK1 = {'S1': 480, 'S2': 127, 'S3': 47}

def project(weeks, lead_growth_by_group, conv_by_group_curve, churn_curve_by_group):
    sim = {g: [[sd,p,pl,n] for sd,p,pl,n in cohorts_by_group[g]] for g in ['S1','S2','S3']}
    cash = CASH_NOW
    day = DAY
    trace = []
    for wk in range(1, weeks+1):
        week_revenue = 0.0
        week_compute = 0.0
        leads_total = 0
        for g in ['S1','S2','S3']:
            churn_rate = churn_curve_by_group[g][min(wk-1,len(churn_curve_by_group[g])-1)]
            for c in sim[g]:
                sd,p,pl,n = c
                if n <= 0: continue
                for d in range(day+1, day+8):
                    if sd < d and (d-sd) % 30 == 0:
                        survivors = n*(1-churn_rate)
                        week_revenue += survivors*p
                        c[3] = survivors
                week_compute += c[3]*usage_of(g,pl)*7*TIER_COMPUTE.get(pl,0.006)
            leads = LEADS_WK1[g]*(lead_growth_by_group[g]**(wk-1))
            leads_total += leads
            conv = conv_by_group_curve[g][min(wk-1,len(conv_by_group_curve[g])-1)]
            new_subs = leads*conv
            for plan, price, frac in NEW_PLAN_MIX[g]:
                n_this = new_subs*frac
                week_revenue += n_this*price
                week_compute += n_this*usage_of(g,plan)*7*TIER_COMPUTE[plan]
                sim[g].append([day+7, price, plan, n_this])
        cost = FIXED_WEEKLY + week_compute + leads_total*0.5
        net = week_revenue - cost
        cash += net
        total_active = sum(sum(c[3] for c in sim[g]) for g in ['S1','S2','S3'])
        trace.append((day+7, round(total_active), round(week_revenue), round(week_compute), round(cost), round(net), round(cash)))
        day += 7
    return trace

print("--- PESSIMISTIC (tier cut backfires for S2: conversion craters, churn spikes; S1/S3 fine) ---")
