import json

with open('week17_cohorts.json') as f:
    cohorts = json.load(f)

CURRENT_DAY = 119
CASH_NOW = 134712.0

PROMO = {"S1": 12.0, "S2": 15.0, "S3": 15.0}
USAGE_PER_CUST = {"A": 69.26, "B": 198.11, "C": 300.0}
TIER_MULT_COST = {2: 0.002, 3: 0.006, 4: 0.012, 5: 0.03}
PLAN_TIER = {"A": 2, "B": 4, "C": 5}
NEW_PLAN_PRICE = {"A": 14.0, "B": 49.0, "C": 150.0}
LEAD_COST = 0.5
BASE_SUBS = 3488.0

def simulate(days_horizon, fail_rate_fn, new_signups_per_day_fn, adaptive_cost=True, capacity_fixed=530.0):
    state = []
    for c in cohorts:
        state.append({"group": c["group_id"], "plan": c["plan"], "price": c["listed_price"],
                       "bday": c["billing_day_mod30"], "n": c["n"]})
    cash = CASH_NOW
    history = {}
    min_subs_seen = BASE_SUBS
    for day_offset in range(1, days_horizon+1):
        day = CURRENT_DAY + day_offset
        week_idx = day_offset // 7
        bucket = day % 30
        revenue = 0.0
        new_state = []
        for row in state:
            if row["bday"] == bucket:
                fr = fail_rate_fn(row["group"], week_idx)
                survivors = row["n"] * (1 - fr)
                eff_price = max(0.0, row["price"] - PROMO.get(row["group"], 0.0))
                revenue += survivors * eff_price
                if survivors > 0.5:
                    nr = dict(row); nr["n"] = survivors
                    new_state.append(nr)
            else:
                new_state.append(row)
        state = new_state
        n_new = new_signups_per_day_fn(day_offset)
        if n_new > 0:
            state.append({"group": "NEW", "plan": "A", "price": NEW_PLAN_PRICE["A"], "bday": bucket, "n": n_new})
        total_subs = sum(r["n"] for r in state)
        total_by_plan = {"A": 0.0, "B": 0.0, "C": 0.0}
        for row in state:
            total_by_plan[row["plan"]] += row["n"]
        compute_cost = sum(total_by_plan[p]*USAGE_PER_CUST[p]*TIER_MULT_COST[PLAN_TIER[p]] for p in ["A","B","C"])
        leads_today = 424.0/7.0
        lead_cost = leads_today * LEAD_COST
        # adaptive dev/ops: scale down as subscriber base shrinks (I would actively manage this),
        # floor to keep minimal viable ops (outage protection) + minimal dev (keep some quality growth)
        if adaptive_cost:
            scale = max(0.20, total_subs / BASE_SUBS)  # don't cut below 20% of original spend
            dev = max(250.0, 1700.0*scale)
            ops = max(300.0, 850.0*scale)
        else:
            dev, ops = 1700.0, 850.0
        total_cost = capacity_fixed + ops + dev + compute_cost + lead_cost
        cash += revenue - total_cost
        if day in (CURRENT_DAY+7, CURRENT_DAY+28, CURRENT_DAY+84, CURRENT_DAY+182):
            history[day] = {"cash": cash, "subs": total_subs, "rev": revenue, "cost": total_cost, "dev": dev, "ops": ops}
    return cash, history

def mk_fail(s1_start, s1_floor, s2_start, s2_floor, s3_start, s3_floor, decay):
    def f(group, week_idx):
        if group == "NEW": group = "S1"
        start = {"S1": s1_start, "S2": s2_start, "S3": s3_start}[group]
        floor = {"S1": s1_floor, "S2": s2_floor, "S3": s3_floor}[group]
        return max(floor, start - decay*week_idx)
    return f

scenarios = {
    "BASE": (mk_fail(0.20,0.06, 0.20,0.05, 0.45,0.12, 0.007), lambda d: 424.0/7.0*0.10),
    "OPT":  (mk_fail(0.14,0.04, 0.14,0.03, 0.30,0.06, 0.012), lambda d: 424.0/7.0*0.25),
    "PESS": (mk_fail(0.32,0.18, 0.34,0.18, 0.65,0.40, 0.003), lambda d: 424.0/7.0*0.01),
}

results = {}
for label, (fr, ns) in scenarios.items():
    cash_final, hist = simulate(182, fr, ns, adaptive_cost=True)
    results[label] = hist
    print(f"\n=== {label} (adaptive cost mgmt) ===")
    for day, d in sorted(hist.items()):
        print(f"day{day} (+{day-CURRENT_DAY}d): cash=${d['cash']:,.0f} subs={d['subs']:,.0f} rev=${d['rev']:,.0f} cost=${d['cost']:,.0f} (dev=${d['dev']:.0f} ops=${d['ops']:.0f})")

print("\n\n=== SUMMARY TABLE (adaptive) ===")
for horizon_day, label in [(126,"+7d"),(147,"+28d"),(203,"+84d"),(301,"+182d")]:
    b = results["BASE"][horizon_day]["cash"]
    o = results["OPT"][horizon_day]["cash"]
    p = results["PESS"][horizon_day]["cash"]
    print(f"{label:6s}: pess=${p:>12,.0f}  base=${b:>12,.0f}  opt=${o:>12,.0f}")
EOF
