import json
with open('week20_book.json') as f:
    book = json.load(f)

CASH0 = 117437.0
DAY0 = 140

TARGET_PROMO = {
    ("S1","A"): 12.0, ("S1","B"): 12.0,
    ("S2","A"): 15.0, ("S2","B"): 15.0,
    ("S3","A"): 25.0, ("S3","B"): 0.0, ("S3","C"): 0.0,
}
COMPUTE_PER_CUST_MONTH = {
    ("S1","A"): 4.61, ("S1","B"): 35.79,
    ("S2","A"): 9.88, ("S2","B"): 57.60,
    ("S3","A"): 24.31, ("S3","B"): 148.25, ("S3","C"): 153.30,
}
CAPACITY_PER_WEEK = {2: 3710.0, 1: 1505.0, 0: 595.0}
LEAD_ACQ_PER_WEEK = 185.0
USAGE_PER_CUST_DAY = {
    "S1": (1404207+696)/7/2612,
    "S2": (263953+106404)/7/324,
    "S3": (246755+170071+3577)/7/149,
}
BASE_FAIL = {"S1": 0.151, "S2": 0.256, "S3": 0.756}

def build_cohorts():
    cohorts = []
    for row in book:
        g, p = row['group_id'], row['plan']
        key = (g,p)
        if key not in TARGET_PROMO: continue
        target = TARGET_PROMO[key]
        ramped = abs(row['avg_promo'] - target) < 1.0
        cohorts.append({'group': g,'plan': p,'bucket': row['bucket'],'n': row['n'],
            'listed_price': row['avg_listed'],'promo': row['avg_promo'],
            'ramped': ramped,'next_checkpoint': None})
    for c in cohorts:
        b = c['bucket']; nc = DAY0 - (DAY0 % 30) + b
        while nc <= DAY0: nc += 30
        c['next_checkpoint'] = nc
    return cohorts

def fail_rate_at_cycle(group, cycle, scenario):
    base = BASE_FAIL[group]
    if scenario == 'plateau': return base
    elif scenario == 'moderate_accel':
        rate = base
        for i in range(cycle+1):
            growth = 1.0 + 0.20*(0.75**i)
            rate = min(0.97, rate*growth) if i>0 else rate
        return rate
    elif scenario == 'aggressive_accel':
        obs_growth = {"S1": 1.50, "S2": 1.90, "S3": 1.10}[group]
        rate = base
        for i in range(cycle):
            decay_growth = 1.0 + (obs_growth-1.0)*(0.7**i)
            rate = min(0.97, rate*decay_growth)
        return rate

def run_scenario(devops_per_week, fail_scenario, days_forward, capacity_downgrade=True):
    sim_cohorts = build_cohorts()
    cash = CASH0
    trajectory = {}
    cycle_count = {"S1":0,"S2":0,"S3":0}
    cur_tier = 2
    def total_pop():
        pop = {"S1":0.0,"S2":0.0,"S3":0.0}
        for c in sim_cohorts: pop[c['group']] += c['n']
        return pop
    for day in range(DAY0+1, DAY0+1+days_forward):
        revenue_today = 0.0
        for c in sim_cohorts:
            if day == c['next_checkpoint'] and c['n'] > 0.01:
                g,p = c['group'], c['plan']
                target = TARGET_PROMO[(g,p)]
                if not c['ramped']:
                    c['promo'] = target; c['ramped'] = True
                eff_price = max(0.0, c['listed_price'] - c['promo'])
                fail = fail_rate_at_cycle(g, cycle_count[g], fail_scenario)
                billed_n = c['n']; survivors = billed_n*(1-fail)
                revenue_today += survivors*eff_price
                c['n'] = survivors; c['next_checkpoint'] += 30; cycle_count[g]+=1
        pop = total_pop()
        compute_today = sum(c['n']*COMPUTE_PER_CUST_MONTH[(c['group'],c['plan'])]/30.0 for c in sim_cohorts)
        total_usage_day = sum(pop[g]*USAGE_PER_CUST_DAY[g] for g in pop)
        if capacity_downgrade:
            if total_usage_day*1.3 < 200000 and cur_tier > 1: cur_tier = 1
            if total_usage_day*1.3 < 50000 and cur_tier > 0: cur_tier = 0
        capacity_today = CAPACITY_PER_WEEK[cur_tier]/7.0
        lead_acq_today = LEAD_ACQ_PER_WEEK/7.0
        devops_today = devops_per_week/7.0
        cash += revenue_today - compute_today - capacity_today - lead_acq_today - devops_today
        offset = day - DAY0
        if offset in (7,28,84,182,364):
            trajectory[offset] = cash
    return trajectory, cash, sum(pop.values())

print("devops=0 (our new setting), all 3 scenarios, full detail incl +7d:")
for scenario in ['plateau','moderate_accel','aggressive_accel']:
    traj, final_cash, final_subs = run_scenario(0, scenario, 364)
    print(scenario, {k: round(v) for k,v in traj.items()}, "end_subs=", round(final_subs))

# weighted blend across scenarios (given 2 straight weeks of acceleration, weight accel scenarios higher)
weights = {'plateau': 0.20, 'moderate_accel': 0.45, 'aggressive_accel': 0.35}
blend = {7:0,28:0,84:0,182:0,364:0}
all_traj = {}
for scenario in weights:
    traj,_,_ = run_scenario(0, scenario, 364)
    all_traj[scenario] = traj
    for k in blend:
        blend[k] += weights[scenario]*traj[k]
print("\nWeighted blend point estimates (devops=0):")
for k in blend:
    print(f"+{k}d: ${blend[k]:,.0f}")

print("\nRange (min-max) across scenarios per horizon, for CI construction:")
for k in [7,28,84,182,364]:
    vals = [all_traj[s][k] for s in weights]
    print(f"+{k}d: min=${min(vals):,.0f} max=${max(vals):,.0f}")
