import json

# Current state (day 147), from real data pulled this session
CASH0 = 113425.0
DAY0 = 147

groups = {
    'S1': {'pop': 2469, 'net_rev_month': 49421.0+134.0, 'usage_day': 75.74, 'cost_per_unit': (2467*0.002+2*0.012)/2469},
