}
for g,d in groups.items():
    d['rev_per_cust_month'] = d['net_rev_month']/d['pop']

# fail rate this week (checkpoint, per-bucket-week rate)
fail_now = {'S1':0.321, 'S2':0.518, 'S3':0.878}
BUCKET_FRAC = 7/30.0  # fraction of population evaluated per week

CAPACITY_COST = {0:85,1:215,2:530,3:1330,4:4000,5:10000,6:28000,7:75000}
CAPACITY_CAP  = {0:50000,1:200000,2:800000,3:2500000,4:8000000,5:25000000,6:80000000,7:300000000}

LEAD_ACQ_WEEKLY = 200.0  # roughly constant

def run_scenario(name, ops_schedule, fail_rate_traj, weeks=76, verbose=False):
    """ops_schedule: function(week_idx)->$/day ops.
       fail_rate_traj: function(week_idx, group)->fail rate for that week."""
    pop = {g: groups[g]['pop'] for g in groups}
    rev_per_cust = {g: groups[g]['rev_per_cust_month'] for g in groups}
    usage_per_cust = {g: groups[g]['usage_day'] for g in groups}
    cost_per_unit = {g: groups[g]['cost_per_unit'] for g in groups}
    cash = CASH0
    tier = 2
    trace = []
    for wk in range(1, weeks+1):
        # attrition
        for g in groups:
            fr = fail_rate_traj(wk, g)
            cancels = pop[g]*BUCKET_FRAC*fr
            pop[g] = max(0.0, pop[g]-cancels)
        total_usage_day = sum(pop[g]*usage_per_cust[g] for g in groups)
        total_usage_week = total_usage_day*7
        # capacity tier decision (downgrade only, based on peak proxy = avg*1.25 safety factor)
        proxy_peak = total_usage_day*1.3
        while tier>0 and proxy_peak < CAPACITY_CAP[tier-1]*0.75:
            tier -= 1
        capacity_cost_week = CAPACITY_COST[tier]*7
        compute_cost_week = sum(pop[g]*usage_per_cust[g]*7*cost_per_unit[g] for g in groups)
        revenue_week = sum(pop[g]*rev_per_cust[g] for g in groups)/30*7
        ops_cost_week = ops_schedule(wk)*7
        net = revenue_week - compute_cost_week - capacity_cost_week - ops_cost_week - LEAD_ACQ_WEEKLY
        cash += net
        trace.append(dict(week=wk, day=DAY0+wk*7, cash=cash, pop_S1=pop['S1'],pop_S2=pop['S2'],pop_S3=pop['S3'],
                           tier=tier, revenue=revenue_week, compute=compute_cost_week, capacity=capacity_cost_week, ops=ops_cost_week))
    return trace

# Scenario H1: ops-restore WORKS - fail rate decays back to healthier levels over ~4 weeks
def fail_h1(wk, g):
    targets_start = {'S1':0.321,'S2':0.518,'S3':0.878}
    targets_end   = {'S1':0.12, 'S2':0.20, 'S3':0.70}   # settles to a still-elevated-but-much-better level (secular drift continues)
    slow_climb    = {'S1':0.0015,'S2':0.002,'S3':0.0}   # slow long-run drift upward after stabilizing (competitor events continue), S3 already near ceiling
    if wk <= 4:
        frac = wk/4.0
        return targets_start[g] + (targets_end[g]-targets_start[g])*frac
    else:
        return min(0.95, targets_end[g] + slow_climb[g]*(wk-4))

def ops_h1(wk):
    if wk <= 3: return 900.0
    elif wk <= 8: return 600.0   # taper to proven maintenance level
    else: return 400.0          # long-run modest maintenance spend

# Scenario H2: ops-restore FAILS to meaningfully help - fail rate stays high / keeps climbing (capped near saturation), we cut losses on spend after a few weeks
def fail_h2(wk, g):
    starts = {'S1':0.321,'S2':0.518,'S3':0.878}
    ceiling = {'S1':0.55,'S2':0.75,'S3':0.95}
    rate_up = {'S1':0.03,'S2':0.02,'S3':0.01}
    v = starts[g] + rate_up[g]*wk
    return min(ceiling[g], v)

def ops_h2(wk):
    if wk <= 4: return 900.0     # try for a month
    else: return 0.0             # give up, back to zero-spend harvest mode

# Scenario H3 (moderate/base case): partial improvement, plateaus at a moderate-bad level
def fail_h3(wk, g):
    targets_start = {'S1':0.321,'S2':0.518,'S3':0.878}
    targets_end   = {'S1':0.22, 'S2':0.35, 'S3':0.80}
    if wk <= 5:
        frac = wk/5.0
        return targets_start[g] + (targets_end[g]-targets_start[g])*frac
    else:
        return min(0.95, targets_end[g] + 0.001*(wk-5))

def ops_h3(wk):
    if wk <= 4: return 900.0
    elif wk <= 10: return 700.0
    else: return 500.0

scenarios = {
    'H1_fix_works':   (ops_h1, fail_h1, 0.40),
    'H2_fix_fails':   (ops_h2, fail_h2, 0.25),
    'H3_partial':     (ops_h3, fail_h3, 0.35),
}

results = {}
for name,(ops_f,fail_f,weight) in scenarios.items():
    tr = run_scenario(name, ops_f, fail_f)
    results[name] = tr

horizons_weeks = {'1wk':1,'4wk':4,'12wk':12,'26wk':26}
print(f"{'scenario':16s}", *[f"{h:>12s}" for h in horizons_weeks], "weight")
for name,tr in results.items():
    w = scenarios[name][2]
    vals = [tr[hw-1]['cash'] for hw in horizons_weeks.values()]
    print(f"{name:16s}", *[f"{v:12,.0f}" for v in vals], w)

# weighted blend
print("\n=== Weighted blend (point estimates) ===")
blend = {}
for h,hw in horizons_weeks.items():
    v = sum(results[name][hw-1]['cash']*scenarios[name][2] for name in scenarios)
    blend[h] = v
    print(h, f"{v:,.0f}")

print("\n=== Range across scenarios (for CI construction) ===")
for h,hw in horizons_weeks.items():
    vals = [results[name][hw-1]['cash'] for name in scenarios]
    print(h, "min:", f"{min(vals):,.0f}", "max:", f"{max(vals):,.0f}")

# End of horizon (day 504, week 51 more from day147 -> (504-147)/7=51 weeks)
print("\n=== end of game (~day 504) ===")
end_wk = round((504-147)/7)
for name,tr in results.items():
    print(name, f"{tr[end_wk-1]['cash']:,.0f}", "pop_S1=", round(tr[end_wk-1]['pop_S1']))
