import json

CASH0 = 110764.0
DAY0 = 154

groups = {
    'S1': {'pop': 2272, 'net_rev_month': 19.026, 'usage_day': 81.0, 'cost_per_unit': 0.002009},
    'S2': {'pop': 241,  'net_rev_month': 32.780, 'usage_day': 178.0, 'cost_per_unit': 0.005569},
    'S3': {'pop': 65,   'net_rev_month': 38.754, 'usage_day': 450.0, 'cost_per_unit': 0.008677},
}

BUCKET_FRAC = 7/30.0
CAPACITY_COST = {0:85,1:215,2:530,3:1330,4:4000,5:10000,6:28000,7:75000}
CAPACITY_CAP  = {0:50000,1:200000,2:800000,3:2500000,4:8000000,5:25000000,6:80000000,7:300000000}
LEAD_ACQ_WEEKLY = 210.0
POP0_TOTAL = sum(d['pop'] for d in groups.values())

def run_scenario(ops_schedule, fail_rate_traj, weeks=51):
    pop = {g: groups[g]['pop'] for g in groups}
    rev_per_cust = {g: groups[g]['net_rev_month'] for g in groups}
    usage_per_cust = {g: groups[g]['usage_day'] for g in groups}
    cost_per_unit = {g: groups[g]['cost_per_unit'] for g in groups}
    cash = CASH0
    tier = 2
    trace = []
    for wk in range(1, weeks+1):
        pop_total_before = sum(pop.values())
        for g in groups:
            fr = fail_rate_traj(wk, g)
            cancels = pop[g]*BUCKET_FRAC*fr
            pop[g] = max(0.0, pop[g]-cancels)
        total_usage_day = sum(pop[g]*usage_per_cust[g] for g in groups)
        proxy_peak = total_usage_day*1.25
        while tier>0 and proxy_peak < CAPACITY_CAP[tier-1]*0.72:
            tier -= 1
        capacity_cost_week = CAPACITY_COST[tier]*7
        compute_cost_week = sum(pop[g]*usage_per_cust[g]*7*cost_per_unit[g] for g in groups)
        revenue_week = sum(pop[g]*rev_per_cust[g] for g in groups)/30*7
        ops_cost_week = ops_schedule(wk, pop_total_before)*7
        net = revenue_week - compute_cost_week - capacity_cost_week - ops_cost_week - LEAD_ACQ_WEEKLY
        cash += net
        trace.append(dict(week=wk, day=DAY0+wk*7, cash=cash, pop_total=sum(pop.values()),
                           tier=tier, revenue=revenue_week, compute=compute_cost_week,
                           capacity=capacity_cost_week, ops=ops_cost_week))
    return trace

# H1: fix keeps working -- fail rates continue improving toward a floor better than pre-crisis
def fail_h1(wk, g):
    start = {'S1':0.261,'S2':0.486,'S3':0.872}
    floor = {'S1':0.16,'S2':0.33,'S3':0.80}
    if wk<=6: return start[g]+(floor[g]-start[g])*(wk/6.0)
    drift = {'S1':0.001,'S2':0.0012,'S3':0.0005}
    return min(0.95, floor[g]+drift[g]*(wk-6))
def ops_h1(wk, pop_total):
    if wk<=2: base=900.0
    elif wk<=6: base=650.0
    elif wk<=14: base=450.0
    else: base=300.0
    return base * max(0.12, pop_total/POP0_TOTAL)

# H2: improvement stalls/reverses -- ops fix only partially offsets ongoing drift
def fail_h2(wk, g):
    start = {'S1':0.261,'S2':0.486,'S3':0.872}
    ceil = {'S1':0.50,'S2':0.65,'S3':0.92}
    up = {'S1':0.018,'S2':0.012,'S3':0.004}
    if wk<=3: return start[g]  # brief plateau then resumes climbing
    return min(ceil[g], start[g]+up[g]*(wk-3))
def ops_h2(wk, pop_total):
    base = 900.0 if wk<=4 else 500.0
    return base * max(0.12, pop_total/POP0_TOTAL)

# H3: partial / muddle-through -- modest further improvement then plateau near current levels
def fail_h3(wk, g):
    start = {'S1':0.261,'S2':0.486,'S3':0.872}
    floor = {'S1':0.22,'S2':0.42,'S3':0.85}
    if wk<=5: return start[g]+(floor[g]-start[g])*(wk/5.0)
    return floor[g]
def ops_h3(wk, pop_total):
    if wk<=3: base=900.0
    elif wk<=10: base=600.0
    else: base=400.0
    return base * max(0.12, pop_total/POP0_TOTAL)

scenarios = {
    'H1_fix_works_well': (ops_h1, fail_h1, 0.50),
    'H2_stalls_worsens': (ops_h2, fail_h2, 0.20),
    'H3_partial_plateau': (ops_h3, fail_h3, 0.30),
}
results = {name: run_scenario(o,f) for name,(o,f,w) in scenarios.items()}

horizons = {'1wk':1,'4wk':4,'12wk':12,'26wk':26}
print("Point estimates by scenario:")
for name,tr in results.items():
    vals = {h: tr[hw-1]['cash'] for h,hw in horizons.items()}
    print(name, {k:round(v) for k,v in vals.items()}, "pop@26wk:", round(tr[25]['pop_total']))

print("\nWeighted blend:")
blend={}
for h,hw in horizons.items():
    v = sum(results[n][hw-1]['cash']*scenarios[n][2] for n in scenarios)
    blend[h]=v
    lo = min(results[n][hw-1]['cash'] for n in scenarios)
    hi = max(results[n][hw-1]['cash'] for n in scenarios)
    print(h, f"point={v:,.0f}  scenario_range=[{lo:,.0f}, {hi:,.0f}]")

end_wk = min(51, round((504-154)/7))
print("\nEnd of game (~day504) by scenario:")
for name,tr in results.items():
    idx = min(end_wk,len(tr))-1
    print(name, f"{tr[idx]['cash']:,.0f}", "pop=", round(tr[idx]['pop_total']))

print("\nWeek-by-week detail, H1 (first 6 weeks):")
for row in results['H1_fix_works_well'][:6]:
    print(row)

print("\nWeek-by-week detail, H3 (first 6 weeks):")
for row in results['H3_partial_plateau'][:6]:
    print(row)

