import json, copy

CASH0 = 111918.0
DAY0 = 161

# Actual per-bucket (billing_day_mod30) population & net-revenue-if-paid, pulled live day161
BUCKETS = {
"S1": {0:[92,1928.0],1:[66,1343.0],2:[78,1606.0],3:[99,2216.0],4:[132,2596.0],5:[146,2876.0],6:[165,3175.0],7:[132,2548.0],8:[106,1872.0],9:[96,1820.0],10:[62,1058.0],11:[41,695.0],12:[91,1713.0],13:[43,733.0],14:[56,948.0],15:[72,1156.0],16:[60,932.0],17:[63,945.0],18:[43,655.0],19:[58,964.0],20:[71,1421.0],21:[73,1421.0],22:[76,1475.0],23:[53,981.0],24:[27,468.0],25:[24,427.0],26:[20,455.0],27:[30,650.0],28:[35,756.0],29:[55,1250.0]},
"S2": {0:[9,351.0],1:[2,75.0],2:[7,202.0],3:[7,256.0],4:[18,636.0],5:[10,410.0],6:[11,336.0],7:[9,326.0],8:[9,346.0],9:[10,300.0],10:[3,136.0],11:[3,92.0],12:[8,298.0],13:[1,14.0],14:[2,108.0],15:[3,82.0],16:[4,36.0],17:[5,74.0],18:[5,150.0],19:[6,274.0],20:[7,208.0],21:[9,346.0],22:[6,154.0],23:[7,234.0],24:[3,76.0],25:[1,64.0],26:[0,0.0],27:[1,21.0],28:[5,138.0],29:[9,351.0]},
"S3": {0:[0,0.0],1:[1,11.0],2:[0,0.0],3:[1,69.0],4:[1,8.0],5:[1,8.0],6:[0,0.0],7:[0,0.0],8:[0,0.0],9:[1,-11.0],10:[0,0.0],11:[0,0.0],12:[0,0.0],13:[1,-6.0],14:[2,38.0],15:[0,0.0],16:[2,48.0],17:[3,32.0],18:[4,257.0],19:[0,0.0],20:[0,0.0],21:[2,16.0],22:[1,-6.0],23:[3,95.0],24:[0,0.0],25:[0,0.0],26:[0,0.0],27:[0,0.0],28:[1,11.0],29:[2,22.0]},
}

USAGE_PER_CUST = {'S1':82.3, 'S2':175.6, 'S3':473.4}   # day161 snapshot
COST_PER_UNIT  = {'S1':0.002014, 'S2':0.005833, 'S3':0.006154}  # plan-mix weighted, day161

CAPACITY_COST = {0:85,1:215,2:530,3:1330,4:4000,5:10000,6:28000,7:75000}
CAPACITY_CAP  = {0:50000,1:200000,2:800000,3:2500000,4:8000000,5:25000000,6:80000000,7:300000000}

def run_scenario(fail_fn, ops_fn, weeks=27):
    buckets = copy.deepcopy(BUCKETS)
    cash = CASH0
    tier = 2
    peak_to_avg = 1.276  # observed this week (287086/224997)
    trace = []
    day = DAY0
    for wk in range(1, weeks+1):
        due = [ (day+i) % 30 for i in range(7) ]
        revenue_week = 0.0
        for g in buckets:
            fr = fail_fn(wk, g)
            for b in due:
                n, rev = buckets[g][b]
                if n <= 0:
                    continue
                avg = rev / n if n > 0 else 0
                survivors = n * (1 - fr)
                revenue_week += survivors * avg
                buckets[g][b] = [survivors, survivors * avg]
        pop = {g: sum(buckets[g][b][0] for b in buckets[g]) for g in buckets}
        pop_total = sum(pop.values())
        total_usage_day = sum(pop[g]*USAGE_PER_CUST[g] for g in pop)
        proj_peak = total_usage_day * peak_to_avg
        # capacity tier auto-adjust (downgrade when safely under, upgrade if overload risk)
        if proj_peak > CAPACITY_CAP[tier]*0.90 and tier < 7:
            tier += 1
        while tier > 0 and proj_peak < CAPACITY_CAP[tier-1]*0.75:
            tier -= 1
        capacity_cost_week = CAPACITY_COST[tier]*7
        compute_cost_week = sum(pop[g]*USAGE_PER_CUST[g]*7*COST_PER_UNIT[g] for g in pop)
        ops_cost_week = ops_fn(wk, pop_total)*7
        lead_acq_week = max(60.0, 150.0*(pop_total/2371.0))
        net = revenue_week - compute_cost_week - capacity_cost_week - ops_cost_week - lead_acq_week
        cash += net
        trace.append(dict(week=wk, day=day+7, cash=cash, pop_total=pop_total, tier=tier,
                           revenue=revenue_week, compute=compute_cost_week, capacity=capacity_cost_week,
                           ops=ops_cost_week, S1=pop.get('S1',0), S2=pop.get('S2',0), S3=pop.get('S3',0)))
        day += 7
    return trace

# ---- Scenario fail-rate functions ----
# BASE case: S1 holds near its excellent new reading (12.5%) with mild reversion + slow drift upward
# (ongoing expectation drift, no dev spend). S2 flat ~50% with slow drift. S3 ~92% flat (terminal).
def fail_base(wk, g):
    if g=='S1': return min(0.30, 0.14 + 0.0007*wk)
    if g=='S2': return min(0.70, 0.50 + 0.0015*wk)
    return 0.92
def ops_base(wk, pop_total):
    if wk<=4: return 900.0
    if wk<=10: return 700.0
    return max(300.0, 700.0*(pop_total/2371.0))

# OPTIMISTIC: fix continues to outperform, S1 drifts down a bit more / stays low, S2 recovers partway
def fail_opt(wk, g):
    if g=='S1': return max(0.09, 0.125 - 0.001*min(wk,10))
    if g=='S2': return max(0.30, 0.50 - 0.004*min(wk,20))
    return 0.85
def ops_opt(wk, pop_total):
    if wk<=4: return 900.0
    if wk<=10: return 650.0
    return max(250.0, 650.0*(pop_total/2371.0))

# PESSIMISTIC: crisis-healing was partly noise/goodwill-bounce; reverts toward worse, competitor
# events keep pushing expectations up faster than we can track with $0 dev spend
def fail_pess(wk, g):
    if g=='S1': return min(0.45, 0.16 + 0.006*wk)
    if g=='S2': return min(0.80, 0.52 + 0.006*wk)
    return 0.95
def ops_pess(wk, pop_total):
    return max(300.0, 900.0*(pop_total/2371.0))

scenarios = {
    'base':        (fail_base, ops_base, 0.50),
    'optimistic':  (fail_opt,  ops_opt,  0.25),
    'pessimistic': (fail_pess, ops_pess, 0.25),
}
results = {name: run_scenario(f,o) for name,(f,o,w) in scenarios.items()}

horizons = {'1wk':1,'4wk':4,'12wk':12,'26wk':26}
print("Point estimates by scenario:")
for name,tr in results.items():
    vals = {h: tr[hw-1]['cash'] for h,hw in horizons.items()}
    print(name, {k:round(v) for k,v in vals.items()}, "pop@1wk:",round(tr[0]['pop_total']), "pop@26wk:", round(tr[25]['pop_total']))

print("\nWeighted blend (point) + scenario min/max range:")
blend={}
for h,hw in horizons.items():
    v = sum(results[n][hw-1]['cash']*scenarios[n][2] for n in scenarios)
    lo = min(results[n][hw-1]['cash'] for n in scenarios)
    hi = max(results[n][hw-1]['cash'] for n in scenarios)
    blend[h]=(v,lo,hi)
    print(h, f"point={v:,.0f}  scenario_range=[{lo:,.0f}, {hi:,.0f}]")

print("\nWeek-by-week detail, BASE (all 27 weeks):")
for row in results['base']:
    print(row['week'], row['day'], f"cash={row['cash']:,.0f}", f"pop={row['pop_total']:.0f}",
          f"tier={row['tier']}", f"rev={row['revenue']:,.0f}", f"compute={row['compute']:,.0f}",
          f"capacity={row['capacity']:,.0f}", f"ops={row['ops']:,.0f}")

